content.text:
Brief:
Un labyrinthe de haies vu du dessus, joué au tour par tour. Le joueur guide un hérisson case par case en glissant le doigt vers une direction. Chaque déplacement coûte un pas, et des pommes posées dans les allées rapportent des points. La partie est gagnée quand le hérisson atteint la sortie, et elle est bloquée si plus aucun pas ne reste. Aucun chronomètre ne presse le joueur.

Plan:
{"gameType":"puzzle-board","input":"swipe-lanes","lang":"fr","loop":"Glissez le doigt pour guider le hérisson case par case dans le labyrinthe de haies, en ramassant des pommes pour marquer des points. La partie est gagnée en atteignant la sortie, et bloquée s'il ne reste plus aucun pas.","slug":"le-herisson-et-le-labyrinthe","style":"paper-cut","title":"Le Hérisson et le Labyrinthe"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Le Hérisson et le Labyrinthe</title>
7| <style>
8|   html, body {
9|     margin: 0;
10|     padding: 0;
11|     width: 100%;
12|     height: 100%;
13|     overflow: hidden;
14|     background: #f4ecd8;
15|     touch-action: none;
16|     font-family: -apple-system, "Segoe UI", Roboto, sans-serif;
17|   }
18|   #game {
19|     display: block;
20|     width: 100vw;
21|     height: 100dvh;
22|     touch-action: none;
23|   }
24| </style>
25| </head>
26| <body>
27| <canvas id="game"></canvas>
28| <script>
29| // ---- Bridge helper (verbatim) ----
30| const CARTRIDGE = {
31|   send(type, payload = {}) {
32|     window.parent.postMessage(
33|       { source: "cartridge", v: 1, type, payload },
34|       "*",
35|     );
36|   },
37| };
38| </script>
39| <script>
40| (function () {
41|   const canvas = document.getElementById("game");
42|   const ctx = canvas.getContext("2d");
43| 
44|   let W = 0, H = 0, DPR = 1;
45| 
46|   function resize() {
47|     DPR = window.devicePixelRatio || 1;
48|     W = window.innerWidth;
49|     H = window.innerHeight;
50|     canvas.width = Math.floor(W * DPR);
51|     canvas.height = Math.floor(H * DPR);
52|     canvas.style.width = W + "px";
53|     canvas.style.height = H + "px";
54|     ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
55|     draw();
56|   }
57|   window.addEventListener("resize", resize);
58| 
59|   // ---- Seeded jitter for paper-cut style ----
60|   function makeRng(seed) {
61|     let s = seed >>> 0;
62|     return function () {
63|       s = (s * 1664525 + 1013904223) >>> 0;
64|       return (s / 4294967296);
65|     };
66|   }
67|   const rng = makeRng(9182);
68|   const jitterCache = new Map();
69|   function jitter(key, amount) {
70|     if (jitterCache.has(key)) return jitterCache.get(key);
71|     const v = (rng() - 0.5) * 2 * amount;
72|     jitterCache.set(key, v);
73|     return v;
74|   }
75| 
76|   const PALETTE = {
77|     bg: "#f4ecd8",
78|     layer: "#e07a5f",
79|     accent: "#3d405b",
80|     highlight: "#81b29a",
81|   };
82| 
83|   // ---- Maze definition ----
84|   // 0 = wall (haie), 1 = path, 2 = apple, 3 = start, 4 = exit
85|   const GRID = [
86|     [1,1,1,0,1,1,1,1,1],
87|     [0,0,1,0,1,0,0,0,1],
88|     [1,1,1,0,1,0,1,1,1],
89|     [1,0,0,0,1,0,1,0,0],
90|     [1,1,1,1,1,0,1,1,1],
91|     [0,0,0,1,0,0,0,0,1],
92|     [1,1,0,1,1,1,1,0,1],
93|     [1,0,0,1,0,0,1,0,1],
94|     [1,1,1,1,0,1,1,1,4],
95|   ];
96|   const ROWS = GRID.length;
97|   const COLS = GRID[0].length;
98|   const START = { r: 0, c: 0 };
99|   const APPLES_SRC = [
100|     {r:0,c:4},{r:2,c:6},{r:4,c:0},{r:6,c:5},{r:8,c:4},{r:3,c:8},{r:7,c:6}
101|   ];
102| 
103|   let state = "title"; // title, playing, win, stuck
104|   let paused = false;
105|   let player = { r: START.r, c: START.c };
106|   let apples = [];
107|   let score = 0;
108|   let moves = 0;
109|   let stepsLeft = 0;
110|   const MAX_STEPS = 40;
111|   let lastMoveDir = null;
112| 
113|   function cellReachable(r, c) {
114|     return r >= 0 && r < ROWS && c >= 0 && c < COLS && GRID[r][c] !== 0;
115|   }
116| 
117|   function resetGameState() {
118|     player = { r: START.r, c: START.c };
119|     apples = APPLES_SRC.map(a => ({ ...a, taken: false }));
120|     score = 0;
121|     moves = 0;
122|     stepsLeft = MAX_STEPS;
123|     lastMoveDir = null;
124|   }
125| 
126|   function backToTitle() {
127|     state = "title";
128|     paused = false;
129|     resetGameState();
130|     draw();
131|   }
132| 
133|   resetGameState();
134| 
135|   function anyLegalMove() {
136|     if (stepsLeft <= 0) return false;
137|     const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
138|     for (const [dr, dc] of dirs) {
139|       const nr = player.r + dr, nc = player.c + dc;
140|       if (cellReachable(nr, nc)) return true;
141|     }
142|     return false;
143|   }
144| 
145|   function tryMove(dr, dc) {
146|     if (state !== "playing" || paused) return;
147|     const nr = player.r + dr, nc = player.c + dc;
148|     if (!cellReachable(nr, nc)) return;
149|     player.r = nr;
150|     player.c = nc;
151|     moves += 1;
152|     stepsLeft -= 1;
153|     lastMoveDir = dc > 0 ? "right" : dc < 0 ? "left" : dr > 0 ? "down" : "up";
154| 
155|     // apple pickup
156|     for (const a of apples) {
157|       if (!a.taken && a.r === nr && a.c === nc) {
158|         a.taken = true;
159|         score += 10;
160|         CARTRIDGE.send("score", { value: score });
161|       }
162|     }
163| 
164|     if (GRID[nr][nc] === 4) {
165|       state = "win";
166|       CARTRIDGE.send("end", { reason: "win", value: score });
167|     } else if (!anyLegalMove()) {
168|       state = "stuck";
169|       CARTRIDGE.send("end", { reason: "stuck", value: score });
170|     }
171|     draw();
172|   }
173| 
174|   // ---- Input: swipe lanes style (adapted to 4-direction grid) ----
175|   let pressX = 0, pressY = 0;
176|   let pressActive = false;
177|   canvas.addEventListener("pointerdown", (event) => {
178|     pressX = event.clientX;
179|     pressY = event.clientY;
180|     pressActive = true;
181|     if (state === "title") {
182|       startGame();
183|     } else if (state === "win" || state === "stuck") {
184|       backToTitle();
185|     }
186|   });
187|   canvas.addEventListener("pointerup", (event) => {
188|     if (!pressActive) return;
189|     pressActive = false;
190|     if (state !== "playing") return;
191|     const dx = event.clientX - pressX;
192|     const dy = event.clientY - pressY;
193|     const SWIPE_FRACTION = 0.08;
194|     const minLen = canvas.clientWidth * SWIPE_FRACTION;
195|     if (Math.abs(dx) < minLen && Math.abs(dy) < minLen) return;
196|     if (Math.abs(dx) > Math.abs(dy)) {
197|       tryMove(0, Math.sign(dx));
198|     } else {
199|       tryMove(Math.sign(dy), 0);
200|     }
201|   });
202| 
203|   window.addEventListener("keydown", (event) => {
204|     if (state === "title") {
205|       if (event.key === "Enter" || event.key === " ") startGame();
206|       return;
207|     }
208|     if (state === "win" || state === "stuck") {
209|       if (event.key === "Enter" || event.key === " ") backToTitle();
210|       return;
211|     }
212|     if (state !== "playing" || paused) return;
213|     if (event.key === "ArrowLeft") tryMove(0, -1);
214|     else if (event.key === "ArrowRight") tryMove(0, 1);
215|     else if (event.key === "ArrowUp") tryMove(-1, 0);
216|     else if (event.key === "ArrowDown") tryMove(1, 0);
217|   });
218| 
219|   function startGame() {
220|     resetGameState();
221|     state = "playing";
222|     CARTRIDGE.send("start");
223|     CARTRIDGE.send("level", { index: 1 });
224|     draw();
225|   }
226| 
227|   // ---- Host bridge commands ----
228|   window.addEventListener("message", (event) => {
229|     const data = event.data;
230|     if (!data || data.source !== "cartridge-host") return;
231|     if (data.type === "pause") paused = true;
232|     if (data.type === "resume") paused = false;
233|     if (data.type === "reset") backToTitle();
234|   });
235| 
236|   // ---- Drawing helpers: paper-cut style ----
237|   function roundedRectPath(x, y, w, h, r, seedKey) {
238|     const pts = [
239|       [x, y], [x + w, y], [x + w, y + h], [x, y + h]
240|     ];
241|     ctx.beginPath();
242|     const jr = (i, axis) => jitter(seedKey + "_" + i + "_" + axis, 1.5);
243|     ctx.moveTo(x + r + jr(0,'x'), y + jr(0,'y'));
244|     ctx.lineTo(x + w - r + jr(1,'x'), y + jr(1,'y'));
245|     ctx.quadraticCurveTo(x + w + jr(1,'qx'), y + jr(1,'qy'), x + w + jr(1,'qx2'), y + r + jr(1,'qy2'));
246|     ctx.lineTo(x + w + jr(2,'x'), y + h - r + jr(2,'y'));
247|     ctx.quadraticCurveTo(x + w + jr(2,'qx'), y + h + jr(2,'qy'), x + w - r + jr(2,'qx2'), y + h + jr(2,'qy2'));
248|     ctx.lineTo(x + r + jr(3,'x'), y + h + jr(3,'y'));
249|     ctx.quadraticCurveTo(x + jr(3,'qx'), y + h + jr(3,'qy'), x + jr(3,'qx2'), y + h - r + jr(3,'qy2'));
250|     ctx.lineTo(x + jr(0,'x2'), y + r + jr(0,'y2'));
251|     ctx.quadraticCurveTo(x + jr(0,'qx'), y + jr(0,'qy'), x + r + jr(0,'qx2'), y + jr(0,'qy2'));
252|     ctx.closePath();
253|   }
254| 
255|   function drawCardPlate(x, y, w, h, color, seedKey) {
256|     ctx.save();
257|     ctx.shadowColor = "rgba(61,64,91,0.35)";
258|     ctx.shadowBlur = 6;
259|     ctx.shadowOffsetY = 3;
260|     roundedRectPath(x, y, w, h, Math.min(w, h) * 0.15, seedKey);
261|     ctx.fillStyle = color;
262|     ctx.fill();
263|     ctx.restore();
264|   }
265| 
266|   function drawTitleScreen() {
267|     ctx.fillStyle = PALETTE.bg;
268|     ctx.fillRect(0, 0, W, H);
269| 
270|     const plateW = Math.min(W * 0.85, 560);
271|     const plateH = Math.min(H * 0.5, 320);
272|     const px = (W - plateW) / 2;
273|     const py = (H - plateH) / 2 - 20;
274|     drawCardPlate(px, py, plateW, plateH, PALETTE.layer, "titleplate");
275| 
276|     ctx.fillStyle = PALETTE.accent;
277|     ctx.textAlign = "center";
278|     ctx.textBaseline = "middle";
279|     const titleSize = Math.max(20, Math.min(34, plateW * 0.075));
280|     ctx.font = "bold " + titleSize + "px sans-serif";
281|     wrapText("Le Hérisson et le Labyrinthe", W / 2, py + plateH * 0.32, plateW * 0.85, titleSize * 1.15);
282| 
283|     ctx.font = Math.max(14, titleSize * 0.5) + "px sans-serif";
284|     ctx.fillText("Glissez pour avancer, ramassez les pommes", W / 2, py + plateH * 0.68, plateW * 0.9);
285| 
286|     // start button plate
287|     const bw = Math.min(220, plateW * 0.6);
288|     const bh = 56;
289|     const bx = W / 2 - bw / 2;
290|     const by = py + plateH + 30;
291|     drawCardPlate(bx, by, bw, bh, PALETTE.highlight, "startbtn");
292|     ctx.fillStyle = PALETTE.accent;
293|     ctx.font = "bold 20px sans-serif";
294|     ctx.fillText("Jouer", W / 2, by + bh / 2 + 1);
295| 
296|     drawHedgehogIcon(W / 2, py - 45, 30);
297|   }
298| 
299|   function wrapText(text, cx, cy, maxWidth, lineHeight) {
300|     const words = text.split(" ");
301|     let lines = [];
302|     let cur = "";
303|     for (const w of words) {
304|       const test = cur ? cur + " " + w : w;
305|       if (ctx.measureText(test).width > maxWidth && cur) {
306|         lines.push(cur);
307|         cur = w;
308|       } else {
309|         cur = test;
310|       }
311|     }
312|     if (cur) lines.push(cur);
313|     const startY = cy - ((lines.length - 1) * lineHeight) / 2;
314|     lines.forEach((line, i) => {
315|       ctx.fillText(line, cx, startY + i * lineHeight);
316|     });
317|   }
318| 
319|   function drawHedgehogIcon(cx, cy, size) {
320|     ctx.save();
321|     ctx.translate(cx, cy);
322|     ctx.shadowColor = "rgba(61,64,91,0.3)";
323|     ctx.shadowBlur = 5;
324|     ctx.shadowOffsetY = 2;
325|     // body
326|     ctx.beginPath();
327|     ctx.ellipse(0, 0, size, size * 0.75, 0, 0, Math.PI * 2);
328|     ctx.fillStyle = PALETTE.accent;
329|     ctx.fill();
330|     // spikes
331|     ctx.fillStyle = PALETTE.layer;
332|     for (let i = -3; i <= 3; i++) {
333|       const ang = -Math.PI / 2 + i * 0.28;
334|       const x1 = Math.cos(ang) * size * 0.5;
335|       const y1 = Math.sin(ang) * size * 0.5;
336|       const x2 = Math.cos(ang) * size * 1.3;
337|       const y2 = Math.sin(ang) * size * 1.3 - size * 0.3;
338|       ctx.beginPath();
339|       ctx.moveTo(x1 - 4, y1);
340|       ctx.lineTo(x2, y2);
341|       ctx.lineTo(x1 + 4, y1);
342|       ctx.closePath();
343|       ctx.fill();
344|     }
345|     ctx.restore();
346|   }
347| 
348|   function drawMaze() {
349|     ctx.fillStyle = PALETTE.bg;
350|     ctx.fillRect(0, 0, W, H);
351| 
352|     const margin = 16;
353|     const boardTop = 90;
354|     const boardW = W - margin * 2;
355|     const boardH = H - boardTop - margin;
356|     const cellSize = Math.min(boardW / COLS, boardH / ROWS);
357|     const gridW = cellSize * COLS;
358|     const gridH = cellSize * ROWS;
359|     const offX = margin + (boardW - gridW) / 2;
360|     const offY = boardTop + (boardH - gridH) / 2;
361| 
362|     // background plate for board
363|     drawCardPlate(offX - 8, offY - 8, gridW + 16, gridH + 16, "#e9dcc0", "boardplate");
364| 
365|     for (let r = 0; r < ROWS; r++) {
366|       for (let c = 0; c < COLS; c++) {
367|         const x = offX + c * cellSize;
368|         const y = offY + r * cellSize;
369|         const val = GRID[r][c];
370|         const key = "cell_" + r + "_" + c;
371|         if (val === 0) {
372|           // hedge (wall)
373|           ctx.save();
374|           ctx.shadowColor = "rgba(61,64,91,0.25)";
375|           ctx.shadowBlur = 4;
376|           ctx.shadowOffsetY = 2;
377|           roundedRectPath(x + 2, y + 2, cellSize - 4, cellSize - 4, cellSize * 0.2, key);
378|           ctx.fillStyle = PALETTE.highlight;
379|           ctx.fill();
380|           ctx.restore();
381|         } else {
382|           // path tile - subtle
383|           roundedRectPath(x + 3, y + 3, cellSize - 6, cellSize - 6, cellSize * 0.15, key + "_path");
384|           ctx.fillStyle = "#f4ecd8";
385|           ctx.fill();
386|           if (val === 4) {
387|             // exit marker
388|             ctx.save();
389|             ctx.fillStyle = PALETTE.accent;
390|             ctx.beginPath();
391|             ctx.arc(x + cellSize / 2, y + cellSize / 2, cellSize * 0.28, 0, Math.PI * 2);
392|             ctx.fill();
393|             ctx.fillStyle = PALETTE.bg;
394|             ctx.font = "bold " + Math.floor(cellSize * 0.32) + "px sans-serif";
395|             ctx.textAlign = "center";
396|             ctx.textBaseline = "middle";
397|             ctx.fillText("S", x + cellSize / 2, y + cellSize / 2 + 1);
398|             ctx.restore();
399|           }
400|         }
401|       }
402|     }
403| 
404|     // apples
405|     for (const a of apples) {
406|       if (a.taken) continue;
407|       const x = offX + a.c * cellSize + cellSize / 2;
408|       const y = offY + a.r * cellSize + cellSize / 2;
409|       drawApple(x, y, cellSize * 0.22);
410|     }
411| 
412|     // player hedgehog
413|     const px = offX + player.c * cellSize + cellSize / 2;
414|     const py = offY + player.r * cellSize + cellSize / 2;
415|     drawHedgehogIcon(px, py, cellSize * 0.28);
416| 
417|     // HUD
418|     drawHUD(offX, gridW);
419| 
420|     if (state === "win" || state === "stuck") {
421|       drawEndOverlay();
422|     } else if (paused) {
423|       drawPauseOverlay();
424|     }
425|   }
426| 
427|   function drawApple(cx, cy, r) {
428|     ctx.save();
429|     ctx.shadowColor = "rgba(61,64,91,0.3)";
430|     ctx.shadowBlur = 4;
431|     ctx.shadowOffsetY = 2;
432|     ctx.beginPath();
433|     ctx.arc(cx, cy, r, 0, Math.PI * 2);
434|     ctx.fillStyle = PALETTE.layer;
435|     ctx.fill();
436|     ctx.restore();
437|     ctx.fillStyle = PALETTE.highlight;
438|     ctx.beginPath();
439|     ctx.ellipse(cx - r * 0.3, cy - r * 1.1, r * 0.35, r * 0.18, -0.4, 0, Math.PI * 2);
440|     ctx.fill();
441|   }
442| 
443|   function drawHUD(offX, gridW) {
444|     const hudH = 60;
445|     drawCardPlate(offX, 14, gridW, hudH, PALETTE.layer, "hudplate");
446|     ctx.fillStyle = "#f4ecd8";
447|     ctx.textAlign = "left";
448|     ctx.textBaseline = "middle";
449|     ctx.font = "bold 18px sans-serif";
450|     ctx.fillText("Score: " + score, offX + 18, 14 + hudH / 2);
451|     ctx.textAlign = "right";
452|     ctx.fillText("Pas restants: " + stepsLeft, offX + gridW - 18, 14 + hudH / 2);
453|   }
454| 
455|   function drawPauseOverlay() {
456|     ctx.fillStyle = "rgba(61,64,91,0.5)";
457|     ctx.fillRect(0, 0, W, H);
458|     const pw = 260, ph = 90;
459|     drawCardPlate(W / 2 - pw / 2, H / 2 - ph / 2, pw, ph, PALETTE.highlight, "pauseplate");
460|     ctx.fillStyle = PALETTE.accent;
461|     ctx.font = "bold 24px sans-serif";
462|     ctx.textAlign = "center";
463|     ctx.textBaseline = "middle";
464|     ctx.fillText("Pause", W / 2, H / 2);
465|   }
466| 
467|   function drawEndOverlay() {
468|     ctx.fillStyle = "rgba(61,64,91,0.55)";
469|     ctx.fillRect(0, 0, W, H);
470|     const pw = Math.min(W * 0.8, 420);
471|     const ph = 220;
472|     const px = W / 2 - pw / 2;
473|     const py = H / 2 - ph / 2;
474|     drawCardPlate(px, py, pw, ph, PALETTE.layer, "endplate");
475|     ctx.fillStyle = "#f4ecd8";
476|     ctx.textAlign = "center";
477|     ctx.textBaseline = "middle";
478|     ctx.font = "bold 28px sans-serif";
479|     const msg = state === "win" ? "Bravo, sorti !" : "Plus aucun pas...";
480|     ctx.fillText(msg, W / 2, py + ph * 0.32);
481|     ctx.font = "20px sans-serif";
482|     ctx.fillText("Score final: " + score, W / 2, py + ph * 0.55);
483|     ctx.font = "16px sans-serif";
484|     ctx.fillText("Touchez pour recommencer", W / 2, py + ph * 0.78);
485|   }
486| 
487|   function draw() {
488|     if (state === "title") {
489|       drawTitleScreen();
490|     } else {
491|       drawMaze();
492|     }
493|   }
494| 
495|   // ---- Boot ----
496|   resize();
497|   draw();
498|   CARTRIDGE.send("boot", { title: "Le Hérisson et le Labyrinthe", gameType: "puzzle-board", lang: "fr" });
499| })();
500| </script>
501| </body>
502| </html>
503|

